package com.bigbuttons.remote
import android.app.Activity
import android.graphics.Typeface
import android.os.Bundle
import android.view.Gravity
import android.view.View
import android.widget.*
class ModePickerActivity:Activity(){override fun onCreate(savedInstanceState:Bundle?){super.onCreate(savedInstanceState);AppPrefs.ensureMigrated(this);render()};private fun render(){val scroll=ScrollView(this).apply{setBackgroundColor(AppColors.Background)};val root=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL};applySystemBarPadding(root,16,14);scroll.addView(root,FrameLayout.LayoutParams(FrameLayout.LayoutParams.MATCH_PARENT,FrameLayout.LayoutParams.WRAP_CONTENT));root.addView(TextView(this).apply{text="Modes";setTextColor(AppColors.Text);textSize=28f;setTypeface(typeface,Typeface.BOLD)});root.addView(TextView(this).apply{text="Choose a setup.";setTextColor(AppColors.Muted);textSize=15f;setPadding(0,dp(4),0,dp(18))});val active=AppPrefs.activeModeIndex(this);repeat(AppPrefs.MODE_COUNT){idx->val m=AppPrefs.mode(this,idx);val card=Button(this).apply{text=if(idx==active)"${m.name}\nSelected" else "${m.name}\n${m.pages.size} page${if(m.pages.size==1)"" else "s"}";gravity=Gravity.CENTER_VERTICAL;textAlignment=View.TEXT_ALIGNMENT_VIEW_START;textSize=18f;setTextColor(AppColors.Text);setTypeface(typeface,Typeface.BOLD);isAllCaps=false;minHeight=0;minWidth=0;setPadding(dp(18),dp(14),dp(18),dp(14));background=rippleBackground(if(idx==active)AppColors.AccentDark else AppColors.SurfaceRaised,20,if(idx==active)AppColors.Accent else AppColors.Border);setOnClickListener{AppPrefs.setActiveModeIndex(this@ModePickerActivity,idx);finish()}};root.addView(card,LinearLayout.LayoutParams(LinearLayout.LayoutParams.MATCH_PARENT,dp(92)).apply{bottomMargin=dp(12)})};root.addView(Button(this).apply{text="BACK";textSize=14f;setTextColor(AppColors.Text);setTypeface(typeface,Typeface.BOLD);isAllCaps=false;background=rippleBackground(AppColors.Surface,16,AppColors.Border);setOnClickListener{finish()}},LinearLayout.LayoutParams(LinearLayout.LayoutParams.MATCH_PARENT,dp(52)).apply{bottomMargin=dp(12)});setContentView(scroll)}}
